"""Generate reviewable contracts only; no production DB or API changes."""
import json
from pathlib import Path

OUT = Path(__file__).parent / "proposedcontracts.json"
tables = []


def f(kind="text", nullable=False, note=None, enum=None):
    d = {"type": kind, "nullable": nullable}
    if note:
        d["description"] = note
    if enum:
        d["enum"] = enum.split("|")
    return d


def ref(table, nullable=False, note=None):
    d = f("uuid", nullable, note)
    d["references"] = table
    return d


def t(name, phase, fields, *, scope="tenant", retention="customer_workspace", immutable=False, unique=None, checks=None, note=""):
    columns = {"id": f("uuid")}
    if scope == "tenant":
        columns["tenant_id"] = ref("tenants")
    columns.update(fields)
    columns["created_at"] = f("timestamptz")
    if not immutable:
        columns["updated_at"] = f("timestamptz")
    tables.append({
        "name": name,
        "phase": phase,
        "scope": scope,
        "description": note,
        "primary_key": ["tenant_id", "id"] if scope == "tenant" else ["id"],
        "columns": columns,
        "unique_constraints": unique or [],
        "check_contracts": checks or [],
        "append_only": immutable,
        "retention_policy": retention,
        "access": "verified_tenant_and_brand_grants_plus_RLS" if scope == "tenant" else "restricted_control_plane_or_public_definitions_only",
    })


