# Materialize explicit FK column pairs, including tenant boundary.
by_name = {x["name"]: x for x in tables}
for table in tables:
    fks = []
    for name, field in table["columns"].items():
        field["introduced_in_phase"] = table["phase"]
        target = field.pop("references", None)
        if not target:
            continue
        target_scope = by_name[target]["scope"]
        tenant_join = target_scope == "tenant"
        assert not tenant_join or table["scope"] == "tenant"
        introduced = max(table["phase"], by_name[target]["phase"])
        field["introduced_in_phase"] = introduced
        fks.append({
            "columns": ["tenant_id", name] if tenant_join else [name],
            "references": {"table": target, "columns": ["tenant_id", "id"] if tenant_join else ["id"]},
            "on_delete": "RESTRICT; deletion workflow applies explicit order or tombstone minimization",
            "introduced_in_phase": introduced,
        })
    table["foreign_keys"] = fks


