# Contract consistency checks; these are not production application tests.
assert len(by_name) == len(tables)
for table in tables:
    assert table["retention_policy"] in contract["retention_policies"]
    assert all(c in table["columns"] for c in table["primary_key"])
    for unique in table["unique_constraints"]:
        assert all(c in table["columns"] for c in unique), (table["name"], unique)
    for fk in table["foreign_keys"]:
        target = by_name[fk["references"]["table"]]
        assert all(c in table["columns"] for c in fk["columns"])
        assert all(c in target["columns"] for c in fk["references"]["columns"])
        assert len(fk["columns"]) == len(fk["references"]["columns"])
        if target["scope"] == "tenant":
            assert fk["columns"][0] == "tenant_id"
assert len({(x["method"], x["path"]) for x in apis}) == len(apis)
OUT.write_text(json.dumps(contract, ensure_ascii=False, indent=2) + "\n")
json.loads(OUT.read_text())
print(json.dumps({"path": str(OUT), "tables": len(tables), "apis": len(apis), "foreign_keys": sum(len(t["foreign_keys"]) for t in tables), "status": "proposal JSON validated"}))
